// ignore_for_file: ditto_missing_visibility
import "dart:typed_data";

import "package:meta/meta.dart";

import "../../analysis/annotations.dart";
import "../../exception.dart";

/// Cross-platform equivalent of `NativeType` from `dart:ffi`
abstract final class CPPointerTarget {}

/// Abstracts over native and WASM pointer types:
/// - on native, it is backed by a `Pointer<Void>`
/// - on WASM, it is backed by the JS representation of a pointer: `{ addr: String, type: String }`
@DoNotMoveOrRename()
@NeedsLocal(native: "asFfi")
abstract interface class CPPointer<T extends CPPointerTarget> {
  int get address;
}

enum CPAttachmentFileOperation {
  copy,
  move,
}

enum CPBase64PaddingMode {
  padded,
  unpadded,
}

/// Abstraction over more sophisticated byte views. Accessing [bytes] requires
/// that [isFreedEarly] is false. Calling [freeEarly] sets [isFreedEarly] to
/// true.
@DoNotMoveOrRename()
abstract class CPBytes {
  Uint8List get bytes;

  bool get isFreedEarly;

  void freeEarly();
}

// Non-opaque structs

class CPChangeHandlerWithQueryResult {
  final CPPointer<CPQueryResult> queryResult;

  const CPChangeHandlerWithQueryResult({
    required this.queryResult,
  });
}

class CPChangeHandlerWithQueryResultAndSignalNext {
  final CPPointer<CPQueryResult> queryResult;
  final void Function() signalNext;

  const CPChangeHandlerWithQueryResultAndSignalNext({
    required this.queryResult,
    required this.signalNext,
  });
}

class CPAttachment {
  final Uint8List id;
  final int len;
  final CPPointer<CPAttachmentHandle> handle;

  CPAttachment({
    required this.id,
    required this.len,
    required this.handle,
  });
}

// Marker types corresponding to the `NativeType` equivalents generated by `ffigen`

abstract final class CPAttachmentHandle implements CPPointerTarget {}

abstract final class CPAuthLoginProvider implements CPPointerTarget {}

abstract final class CPConnectionRequest implements CPPointerTarget {}

abstract final class CPCString implements CPPointerTarget {}

@DoNotMoveOrRename()
abstract final class CPDitto implements CPPointerTarget {}

typedef CPStore = CPDitto;

abstract final class CPDiffer implements CPPointerTarget {}

abstract final class CPDittoTransport implements CPPointerTarget {}

abstract final class CPDittoTransportConfig implements CPPointerTarget {}

abstract final class CPDocument implements CPPointerTarget {}

abstract final class CPDocumentID implements CPPointerTarget {}

abstract final class CPError implements CPPointerTarget {}

abstract final class CPIdentityConfig implements CPPointerTarget {}

abstract final class CPLiveQuery implements CPPointerTarget {}

abstract final class CPLoginProvider implements CPPointerTarget {}

abstract final class CPQueryResult implements CPPointerTarget {}

abstract final class CPQueryResultItem implements CPPointerTarget {}

abstract final class CPReadTransaction implements CPPointerTarget {}

abstract final class CPSyncSubscription implements CPPointerTarget {}

abstract final class CPWriteTransaction implements CPPointerTarget {}

abstract final class CPTransaction implements CPPointerTarget {}

abstract final class CPStoreObserver implements CPPointerTarget {}

/// Represents the result of a login attempt.
@external
final class AuthResponse {
  /// JSON-formatted client info returned by the authentication webhook, if any.
  /// This field is populated for both successful and failed login attempts and
  /// is only `null` when no client info was provided by the webhook.
  ///
  /// See Ditto's online documentation for more information on how to provide
  /// client info using an authentication webhook.
  final String? clientInfo;

  /// If the login attempt was successful, this property will be `null`. If the
  /// login attempt failed, this property will contain a [DittoException] object
  /// with details about the error.
  final DittoException? exception;

  const AuthResponse(this.clientInfo, this.exception);
}

/// The severity of a logging event
@external
enum LogLevel {
  error,
  warning,
  info,
  debug,
  verbose,
}

/// This is maintained by-hand whenever `ffi/src/result/error.rs` changes
@internal
enum CPErrorCode {
  activationLicenseTokenExpired,
  activationLicenseTokenInvalid,
  activationLicenseUnsupportedFutureVersion,
  activationNotActivated,
  activationUnnecessary,
  authenticationExpirationHandlerMissing,
  base64Invalid,
  cborInvalid,
  cborUnsupported,
  crdt,
  differIdentityKeyPath,
  dqlEvaluationError,
  dqlInvalidQueryArgs,
  dqlQueryCompilation,
  dqlUnsupported,
  encryptionExtraneousPassphraseGiven,
  encryptionPassphraseInvalid,
  encryptionPassphraseNotGiven,
  jsFloatingStoreOperation,
  ioAlreadyExists,
  ioNotFound,
  ioOperationFailed,
  ioPermissionDenied,
  lockedDittoWorkingDirectory,
  parameterQuery,
  storeDatabase,
  storeDocumentId,
  storeDocumentNotFound,
  storeQuery,
  storeTransactionReadOnly,
  transport,
  unsupported,
  validationDepthLimitExceeded,
  validationInvalidCbor,
  validationInvalidJson,
  validationInvalidTransportConfig,
  validationInvalidDittoConfig,
  validationNotAMap,
  validationSizeLimitExceeded,
  unknown,
  internal,
  ;

  bool get shouldBeError =>
      this == CPErrorCode.unknown || this == CPErrorCode.internal;
}

enum CPTransportConfigMode {
  platformDependent,
  platformIndependent,
}
